CREATE TABLE equipment(id text PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,serial_number text,location text,unit text NOT NULL CHECK(unit IN ('use','hour','day')),unit_price numeric(14,2) CHECK(unit_price>=0),status text NOT NULL DEFAULT 'ready' CHECK(status IN ('ready','maintenance','out_of_service')),reason text,version integer NOT NULL DEFAULT 1,created_by text REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE equipment_usage(id text PRIMARY KEY,equipment_id text NOT NULL REFERENCES equipment(id),admission_id text NOT NULL REFERENCES admissions(id),charge_id text UNIQUE NOT NULL REFERENCES charges(id),name_snapshot text NOT NULL,code_snapshot text NOT NULL,unit_snapshot text NOT NULL,quantity numeric NOT NULL CHECK(quantity>0),unit_price numeric(14,2) NOT NULL CHECK(unit_price>=0),amount numeric(14,2) NOT NULL CHECK(amount>=0),used_at timestamptz NOT NULL,notes text,actor_id text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX equipment_usage_admission ON equipment_usage(admission_id,created_at);
